inline Service::Service(): srpc::RPCService("AuthService")
{
	this->srpc::RPCService::add_method("Register",
		[this](srpc::RPCWorker& worker) ->int {
			return ServiceRPCCallImpl(this, worker, &Service::Register);
		});

	this->srpc::RPCService::add_method("Login",
		[this](srpc::RPCWorker& worker) ->int {
			return ServiceRPCCallImpl(this, worker, &Service::Login);
		});
}

